import { closeSync, existsSync, openSync, readFileSync, readSync, statSync } from "node:fs";
import { join } from "node:path";
import { listFiles } from "../core/files";
import { matchesAny } from "../core/glob";
import { LOCK_FILE, serializeLock } from "../model/lock";
import type { BuildResult } from "../pipeline";
import { GENERATED_MARK, LEGACY_GENERATED_MARK } from "./header";

export interface Change {
  path: string;
  kind: "create" | "update" | "delete";
}

export interface WorkspacePlan {
  changes: Change[];
  /** Paths that exist, were not generated by this tool, and are in the tool's way. */
  collisions: string[];
  lockText: string;
  lockChanged: boolean;
}

/**
 * §6 step 7: compares the in-memory build with the repo. Reads only generated and managed
 * paths, and never plans a change to a protected one (§4.5).
 */
export function planWorkspace(
  repoRoot: string,
  build: Pick<BuildResult, "tree" | "lock" | "previousLock" | "managedDirs" | "protectedPaths">,
): WorkspacePlan {
  const { tree, lock, previousLock, managedDirs, protectedPaths } = build;
  const isProtected = (path: string) => matchesAny(path, protectedPaths);
  const owned = new Set(Object.keys(previousLock?.files ?? {}).filter((p) => !isProtected(p)));
  const isOwned = (path: string) => owned.has(path) || hasGeneratedMark(join(repoRoot, path));
  const changes: Change[] = [];
  const collisions = new Set<string>();

  for (const path of tree.paths()) {
    const abs = join(repoRoot, path);
    const file = tree.get(path);
    if (!file) continue;
    if (!existsSync(abs)) {
      changes.push({ path, kind: "create" });
      continue;
    }
    if (!isOwned(path)) {
      collisions.add(path);
      continue;
    }
    const same = Buffer.from(file.content).equals(readFileSync(abs));
    const sameMode = ((statSync(abs).mode & 0o111) !== 0) === file.executable;
    if (!same || !sameMode) changes.push({ path, kind: "update" });
  }

  for (const dir of managedDirs) {
    if (!existsSync(join(repoRoot, dir))) continue;
    for (const file of listFiles(join(repoRoot, dir))) {
      const path = `${dir}/${file}`;
      if (!tree.has(path) && !isProtected(path) && !isOwned(path)) collisions.add(path);
    }
  }

  for (const path of owned) {
    if (!tree.has(path) && existsSync(join(repoRoot, path))) changes.push({ path, kind: "delete" });
  }

  const lockText = serializeLock(lock);
  const lockPath = join(repoRoot, LOCK_FILE);
  const lockChanged = !existsSync(lockPath) || readFileSync(lockPath, "utf8") !== lockText;
  return { changes, collisions: [...collisions].sort(), lockText, lockChanged };
}

export function hasGeneratedMark(abs: string): boolean {
  if (!existsSync(abs)) return false;
  const fd = openSync(abs, "r");
  try {
    const buffer = Buffer.alloc(1024);
    const read = readSync(fd, buffer, 0, buffer.length, 0);
    const head = buffer.subarray(0, read).toString("utf8");
    return head.includes(GENERATED_MARK) || head.includes(LEGACY_GENERATED_MARK);
  } finally {
    closeSync(fd);
  }
}
